def inkc(c):
    c=c.lstrip('#')
    if len(c)==3:c=''.join(x*2 for x in c)
    try:r_,g,bb=[int(c[i:i+2],16)/255 for i in(0,2,4)]
    except Exception:return '#0B0B0D'
    f=lambda v:v/12.92 if v<=.03928 else((v+.055)/1.055)**2.4
    L=.2126*f(r_)+.7152*f(g)+.0722*f(bb)
    return '#0B0B0D' if (L+.05)/.0555>1.05/(L+.05) else '#FFFFFF'
