def fixh(body):
    hs=re.findall(r'<h([1-6])[ >]',body)
    k=body.find('<h3')
    if k<0 or (hs and '2' in hs[:hs.index('3')]) :return body
    s=body.rfind('<section',0,k)
    if s<0:return body
    t=body.index('>',s)+1
    return body[:t]+'<h2 class="sr-only">Overview</h2>'+body[t:]
def pgclass(path):
    if path=='index.html':return 'pg-home'
    if path=='services.html' or path.startswith('services/'):return 'pg-services'
    if path.startswith('work/') or path=='portfolio.html':return 'pg-portfolio'
    if path.startswith('insights/'):return 'pg-blog'
    m={'about.html':'pg-about','contact.html':'pg-contact','faq.html':'pg-faq','process.html':'pg-process','pricing.html':'pg-pricing','start-a-project.html':'pg-start','404.html':'pg-e404'}
    return m.get(path,'pg-default')
