        body=f'<section class="ph"><div class="wrap">{crumbs(2,[("Insights","insights/index.html"),(c,None)])}<span class="eyebrow">Category</span><h1 style="margin-top:1rem">{c}</h1></div></section><section><div class="wrap">'+(f'<div class="bg">{"".join(acard(b,2,"h2") for b in L)}</div>' if L else '<p class="stat warn show">No articles in this category yet. New ones are on the way.</p>')+f'<p style="margin-top:2rem"><a class="tl" href="../index.html">← All insights</a></p></div></section>'
